// Characterization tests: pin CURRENT behaviour of order totals, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 100, E: 100.01, F: 33.33, G: 19.99 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalFor = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['sums multiple lines', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 71],
  ['fractional total is floored, not rounded', [{ sku: 'B', qty: 1 }], 25],
  ['exactly 100 gets no discount (threshold is strict >)', [{ sku: 'D', qty: 1 }], 100],
  ['100.01 gets 10% off then floored', [{ sku: 'E', qty: 1 }], 90],
  ['110 -> 99', [{ sku: 'A', qty: 11 }], 99],
  ['200 -> 180', [{ sku: 'D', qty: 2 }], 180],
  ['1000 -> 900 (flat 10%, no tiers for larger orders)', [{ sku: 'D', qty: 10 }], 900],
  ['discounted fraction floored: 33.33*4=133.32 -> 119.988 -> 119', [{ sku: 'F', qty: 4 }], 119],
  ['floor of discounted float: 19.99*10=199.9 -> 179.91 -> 179', [{ sku: 'G', qty: 10 }], 179],
  ['zero qty line contributes nothing', [{ sku: 'A', qty: 0 }], 0],
  ['negative qty reduces total (not validated)', [{ sku: 'A', qty: 1 }, { sku: 'A', qty: -3 }], -20],
  ['unknown sku (undefined price) yields NaN -> null in JSON', [{ sku: 'ZZZ', qty: 1 }], null],
]
for (const [name, items, expected] of cases) {
  test(`total: ${name}`, async () => assert.equal(await totalFor(items), expected))
}

test('response shape and sequential string ids; GET returns stored order', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 1 }] })
  const order = await res.json()
  assert.deepEqual(Object.keys(order), ['id', 'items', 'total'])
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, [{ sku: 'A', qty: 1 }])
  const got = await fetch(`${base}/orders/${order.id}`)
  assert.equal(got.status, 200)
  assert.deepEqual(await got.json(), order)
})

test('validation: missing/empty/invalid items -> 400', async () => {
  for (const [body, raw] of [[{}], [{ items: [] }], [{ items: 'x' }], [null, '{bad']]) {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('unknown order id returns 200 with error body (quirk)', async () => {
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown route -> 404', async () => {
  const res = await fetch(`${base}/nothing`)
  assert.equal(res.status, 404)
  assert.deepEqual(await res.json(), { error: 'no route' })
})
EOF
